ALTER TABLE "Member" ADD COLUMN "birthday" TEXT, ADD COLUMN "birthdayChangedYear" INTEGER;
CREATE TABLE "MarketingProgram" ("kind" TEXT PRIMARY KEY CHECK ("kind" IN ('BIRTHDAY','WELCOME')), "enabled" BOOLEAN NOT NULL DEFAULT false, "templateId" TEXT, "actorId" TEXT, "version" INTEGER NOT NULL DEFAULT 1, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO "MarketingProgram" ("kind") VALUES ('BIRTHDAY'), ('WELCOME');
CREATE TABLE "MarketingGrant" ("id" TEXT PRIMARY KEY, "kind" TEXT NOT NULL REFERENCES "MarketingProgram"("kind") ON DELETE RESTRICT, "memberId" TEXT NOT NULL REFERENCES "Member"("id") ON DELETE RESTRICT, "period" TEXT NOT NULL, "templateId" TEXT NOT NULL, "originalTemplateId" TEXT NOT NULL, "programVersion" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING' CHECK ("status" IN ('PENDING','FAILED','SUCCEEDED')), "attempts" INTEGER NOT NULL DEFAULT 0, "couponId" TEXT UNIQUE, "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE ("kind","memberId","period"));
CREATE INDEX "MarketingGrant_status_createdAt_idx" ON "MarketingGrant"("status","createdAt");
